<script setup lang="ts">
import {ElButton, ElSelect, ElOption, ElTable, ElTableColumn, ElPagination, vLoading} from 'element-plus'
import {ref,watch} from 'vue'
import {api,type Account} from '../../api'
import {base,reasonText,money,incomeLabel,type DiningOrder,type Restaurant,type PageResult} from './types'
import './dining.css'
const props=defineProps<{account:Account}>()
const items=ref<DiningOrder[]>([]),restaurants=ref<Restaurant[]>([]),restaurantId=ref(''),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),detail=ref<DiningOrder|null>(null),detailLoading=ref(false),detailError=ref(''),detailId=ref('')
let generation=0,detailGeneration=0
async function load(){const current=++generation;loading.value=true;items.value=[];error.value='';try{const result=await api<PageResult<DiningOrder>>(`${base}/orders?${new URLSearchParams({restaurantId:restaurantId.value,page:String(page.value),pageSize:'20'})}`);if(current===generation){items.value=result.items;total.value=result.total}}catch(e){if(current===generation)error.value=reasonText(e)}finally{if(current===generation)loading.value=false}}
async function view(id:string){const current=++detailGeneration;detailId.value=id;detail.value=null;detailError.value='';detailLoading.value=true;try{const result=await api<DiningOrder>(`${base}/orders/${id}`);if(current===detailGeneration)detail.value=result}catch(e){if(current===detailGeneration)detailError.value=reasonText(e)}finally{if(current===detailGeneration)detailLoading.value=false}}
function close(){detailGeneration++;detailId.value='';detail.value=null}
async function initialize(){restaurants.value=[];close();load();try{restaurants.value=(await api<PageResult<Restaurant>>(`${base}/restaurants?pageSize=100`)).items}catch(e){error.value=`餐饮店筛选读取失败：${reasonText(e)}`}}
watch(()=>props.account.accountId,initialize,{immediate:true})
</script>
<template><section class="page-content dining-page"><header class="page-heading"><div><h1>餐饮联盟订单</h1><p>订单地址与桌号来自扫码时的餐饮店信息，由锁定前置仓履约。</p></div></header><section class="panel"><form class="toolbar" @submit.prevent="page=1;load()"><el-select v-model="restaurantId" aria-label="筛选餐饮店" clearable placeholder="全部餐饮店" style="width:280px"><el-option v-for="r in restaurants" :key="r.id" :value="r.id" :label="r.name"/></el-select><el-button native-type="submit" :loading="loading">查询</el-button></form><p v-if="error" role="alert" class="error">{{error}} <el-button @click="initialize">重试</el-button></p><el-table v-loading="loading" :data="items" empty-text="暂无餐饮联盟订单"><el-table-column prop="orderNo" label="订单号" min-width="180"/><el-table-column label="餐饮店 / 桌号" min-width="180"><template #default="{row}">{{row.restaurantName}} · {{row.tableNumber}}</template></el-table-column><el-table-column label="履约仓" min-width="160"><template #default="{row}">{{row.fulfillmentStore.name}}</template></el-table-column><el-table-column label="状态" min-width="120"><template #default="{row}">{{({PENDING_PAYMENT:'待付款',PAID:'已付款',CLOSED:'已关闭'} as Record<string,string>)[row.status]||row.status}}</template></el-table-column><el-table-column label="实付" width="120"><template #default="{row}">{{money(row.payableFen)}}</template></el-table-column><el-table-column label="佣金" min-width="160"><template #default="{row}">{{money(row.commission.commissionFen)}} · {{incomeLabel(row.commission.status)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link @click="view(row.id)">查看详情</el-button></template></el-table-column></el-table><el-pagination :current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="page=$event;load()"/></section><section v-if="detailId" class="panel" aria-label="联盟订单详情"><header class="toolbar"><h2>订单详情</h2><el-button @click="close">关闭详情</el-button></header><p v-if="detailLoading" role="status">正在读取订单详情…</p><p v-if="detailError" role="alert" class="error">{{detailError}} <el-button @click="view(detailId)">重试</el-button></p><template v-if="detail"><p>{{detail.orderNo}} · {{detail.restaurantName}} · 桌号 {{detail.tableNumber}}</p><p>配送地址：{{detail.address}}</p><p>履约前置仓：{{detail.fulfillmentStore.name}}</p><el-table :data="detail.lines"><el-table-column prop="productName" label="商品"/><el-table-column prop="skuCode" label="SKU"/><el-table-column label="数量"><template #default="{row}">{{row.quantity}} {{row.saleUnit}}</template></el-table-column><el-table-column label="实付"><template #default="{row}">{{money(row.payableFen)}}</template></el-table-column></el-table><p>佣金 {{money(detail.commission.commissionFen)}} · {{incomeLabel(detail.commission.status)}}</p><p v-if="detail.commission.reason">{{detail.commission.reason}}</p><RouterLink v-if="account.permissionCodes.includes('order.read')" :to="`/orders/${detail.id}`"><el-button>进入统一订单履约详情</el-button></RouterLink></template></section></section></template>
